    },
    "StoreArtifacts": {
      "Type": "Parallel",
      "Branches": [
        {
          "StartAt": "StoreOriginal",
          "States": {
            "StoreOriginal": {
              "Type": "Pass",
              "End": true
            }
          }
        },
        {
          "StartAt": "StoreRedacted",
          "States": {
            "StoreRedacted": {
              "Type": "Pass",
              "End": true
            }
          }
        }
      ],
      "Next": "UpdateDynamoDB"
    },
    "UpdateDynamoDB": {
      "Type": "Task",
      "Resource": "arn:aws:states:::dynamodb:putItem",
      "Parameters": {
        "TableName": "contracts-index",
        "Item": {
          "contractId": {"S": "$($.contractId)"},
          "origKey": {"S": "$($.origKey)"},
          "redactedKey": {"S": "$($.redactedKey)"},
          "docType": {"S": "$($.docType)"},
          "redactionScore": {"N": "$($.redactionScore)"}
        }
      },
      "End": true
    }
  }
